# -*- coding: utf-8 -*-
"""Self-contained shippable res30 policy (plan-23 P23-8).

Submission-kernel compatible: imports only numpy + the occ7 chain
(which the notebook assembles verbatim). The slot feature machinery
is embedded (mirror of slot_linear/nn_model deploy path at the
dims slot_resid.npz was trained on: FZ 18, FA 14, FG 11); no
slot_linear / nn_model / torch dependency. Stdlib imports are lazy
(inside methods): the assembled notebook cell carries only this class
block + RESID30_W_B64, so module-level stdlib imports would be lost.

RESID30_W_B64 is GENERATED by tools/make_ship_weights.py from
smart_buildings/results/slot_runs/slot_resid.npz -- do not hand-edit.
"""
import numpy as np

from smart_buildings.baselines.occ_gated7 import OccGated7Policy

RESID30_W_B64 = ""


class Resid30ShipPolicy(OccGated7Policy):
    """P23-8: occ7 authority + embedded residual slot heads (scale 0.30).

    Behavior target: probe_slot_res30 with f32 weights (P21-3 bars:
    f32/f64 cont diff < 1e-4, discrete equality, determinism).
    """

    KEY = "occ_resid30"
    RESID_SCALE = 0.30
    N_SLOTS = 288
    BLEND = (1, 2, 1)

    # -- embedded slot machinery (deploy path only) ----------------------
    @staticmethod
    def _slot_of_day(hod_sin, hod_cos):
        import math
        angle = math.atan2(hod_sin, hod_cos)
        if angle < 0:
            angle += 2.0 * math.pi
        frac = angle / (2.0 * math.pi)
        return min(287, int(frac * 288 + 1e-4))

    @staticmethod
    def _bank_of_day(dow_sin, dow_cos):
        import math
        angle = math.atan2(dow_sin, dow_cos)
        if angle < 0:
            angle += 2.0 * math.pi
        day = int(7.0 * angle / (2.0 * math.pi) + 1e-4) % 7
        return 0 if day < 5 else 1

    class _FCtx:
        """Minimal FeatureContext (deploy fields only, no torch)."""

        def __init__(self, meta):
            self.names = list(meta["observation_field_names"])
            self.idx = {n: i for i, n in enumerate(self.names)}
            self.norm = meta["observation_normalization_metadata"]
            zn = self.norm["zone_air_temperature_sensor"]
            self.z_mean, self.z_std = zn["sample_mean"], zn["sample_std"]

            import re

            def _ns(name):
                m = re.search(r"(\d+)", name)
                return int(m.group(1)) if m else 0

            ahu_keys = sorted(meta["ahu_zone_assignments"].keys(), key=_ns)
            temp_idx = meta["temp_indices"]
            n_ahu = min(len(temp_idx), len(ahu_keys))
            self.ahus = ahu_keys[:n_ahu]
            self.rooms = []
            for ahu_i, ahu in enumerate(self.ahus):
                for room in meta["ahu_zone_assignments"][ahu]:
                    vav = room.replace("room_", "VAV_")
                    temp_field = f"{vav}_zone_air_temperature_sensor"
                    if temp_field not in self.idx:
                        continue
                    heat_field = (f"{vav}_zone_air_heating_temperature"
                                  f"_setpoint_sensor")
                    cool_field = (f"{vav}_zone_air_cooling_temperature"
                                  f"_setpoint_sensor")
                    act = meta["zone_action_indices"].get(vav, {})
                    self.rooms.append({
                        "temp_obs": self.idx[temp_field],
                        "heat_obs": self.idx.get(heat_field, -1),
                        "cool_obs": self.idx.get(cool_field, -1),
                        "damp_obs": self.idx.get(
                            f"{vav}_supply_air_damper_percentage_command",
                            -1),
                        "reheat_obs": self.idx.get(
                            f"{vav}_reheat_valve_percentage_command", -1),
                        "damp_act": act.get(
                            "supply_air_damper_percentage_command"),
                        "reheat_act": act.get(
                            "reheat_valve_percentage_command"),
                        "ahu": ahu_i,
                    })
            self.rooms = [r for r in self.rooms
                          if r["damp_act"] is not None
                          and r["reheat_act"] is not None]
            self.Z = len(self.rooms)
            self.ahu_cols = []
            for ahu in self.ahus:
                p = f"ahs_{ahu}_"
                self.ahu_cols.append({
                    s: self.idx.get(f"{p}{s}", -1) for s in (
                        "outside_air_temperature_sensor",
                        "supply_air_temperature_sensor",
                        "supply_air_static_pressure_sensor",
                        "supply_air_flowrate_sensor",
                        "recirculation_percentage_command",
                        "cooling_request_count",
                        "supervisor_run_command",
                    )})
            self.A = len(self.ahus)
            pressure_indices = meta["pressure_indices"]
            recirculation_indices = meta["recirculation_indices"]
            water_indices = meta["water_indices"]
            self.ahu_actions = [{
                "temp_idx": temp_idx[i],
                "pressure_idx": (pressure_indices[i]
                                 if i < len(pressure_indices) else None),
                "recirc_idx": (recirculation_indices[i]
                               if i < len(recirculation_indices) else None),
                "run_disc_idx": i,
            } for i in range(self.A)]
            self.water = {
                "water_temp_idx": (water_indices[0]
                                   if water_indices else None),
                "water_pressure_idx": (pressure_indices[-1]
                                       if len(pressure_indices) > self.A
                                       else None),
                "water_discrete_idx": int(meta["n_discrete_action"]) - 1,
            }
            self.oat_cols = [
                i for i, nm in enumerate(self.names)
                if nm.endswith("_outside_air_temperature_sensor")]

        def _kelvin(self, v, key):
            entry = self.norm.get(key)
            if entry is not None and abs(float(np.mean(v))) <= 150.0:
                return (v * entry["sample_std"] + entry["sample_mean"])
            return v

        def room_feats(self, obs):
            Z, F = self.Z, 8
            feats = np.zeros((Z, F), dtype=np.float32)
            oat_all = None
            if self.oat_cols:
                cols = obs[self.oat_cols]
                oat_all = self._kelvin(np.asarray(cols).mean(axis=-1),
                                       "outside_air_temperature_sensor")
            for k, r in enumerate(self.rooms):
                t_K = obs[r["temp_obs"]] * self.z_std + self.z_mean
                sp_h = obs[r["heat_obs"]] if r["heat_obs"] >= 0 else 291.0
                sp_c = obs[r["cool_obs"]] if r["cool_obs"] >= 0 else 297.0
                feats[k, 0] = np.clip((sp_c - t_K) / 8.0, -1.5, 1.5)
                feats[k, 1] = np.clip((t_K - sp_h) / 8.0, -1.5, 1.5)
                feats[k, 2] = (0.5 * (sp_h + sp_c) - 294.0) / 10.0
                feats[k, 3] = np.clip((sp_c - sp_h) / 6.0, -2.0, 2.0)
                if oat_all is not None:
                    feats[k, 4] = np.clip((t_K - oat_all) / 12.0, -2.0, 2.0)
                if r["damp_obs"] >= 0:
                    feats[k, 5] = obs[r["damp_obs"]]
                if r["reheat_obs"] >= 0:
                    feats[k, 6] = obs[r["reheat_obs"]]
                feats[k, 7] = (t_K - 294.0) / 6.0
            return feats

    class _SFeat:
        """Minimal SlotFeatures (FZ=18/FA=14/FG=11 deploy path)."""

        FZ, FA, FG = 18, 14, 11

        def __init__(self, meta):
            self.ctx = Resid30ShipPolicy._FCtx(meta)
            names = self.ctx.names
            idx = self.ctx.idx
            get = lambda *ns: next((idx[n] for n in ns if n in idx), -1)
            self.dow_sin = idx["dow_sin_000"]
            self.dow_cos = idx["dow_cos_000"]
            self.hod_sin = idx["hod_sin_000"]
            self.hod_cos = idx["hod_cos_000"]
            self.occ_idx = get("num_occupants")
            self.now_idx = get("comfort_mode_now")
            self.soon_idx = get("comfort_mode_soon")
            self.hws_temp = get("hws_supply_water_temperature_sensor")
            self.hws_press = get("hws_differential_pressure_sensor")
            self.hws_run = get("hws_run_status",
                               "hws_supervisor_run_command")
            self.reset()

        def reset(self):
            self._prev_t = None
            self._ema_t = None
            self._int_z = None
            self._heat_ema = None
            self._cool_ema = None
            self._int_w = 0.0

        @staticmethod
        def _clip(v, lo=-2.0, hi=2.0):
            return np.clip(v, lo, hi)

        def _water_kelvin(self, obs):
            if self.hws_temp < 0:
                return 330.0
            v = float(obs[self.hws_temp])
            return v if v > 150.0 else v * 20.0 + 330.0

        def _oat_kelvin(self, obs):
            cols = self.ctx.oat_cols
            if not cols:
                return 280.0
            v = float(np.mean([obs[i] for i in cols]))
            entry = self.ctx.norm.get("outside_air_temperature_sensor")
            if entry is not None and abs(v) <= 150.0:
                return v * entry["sample_std"] + entry["sample_mean"]
            return v

        def _sat_kelvin(self, obs, ahu_i):
            cols = self.ctx.ahu_cols[ahu_i]
            i = cols["supply_air_temperature_sensor"]
            if i < 0:
                return 291.0
            v = float(obs[i])
            entry = self.ctx.norm.get("supply_air_temperature_sensor")
            if entry is not None and abs(v) <= 150.0:
                return v * entry["sample_std"] + entry["sample_mean"]
            return v

        def step(self, obs):
            P = Resid30ShipPolicy
            obs = np.asarray(obs, dtype=np.float64)
            ctx = self.ctx
            bank = P._bank_of_day(obs[self.dow_sin], obs[self.dow_cos])
            slot = P._slot_of_day(obs[self.hod_sin], obs[self.hod_cos])
            room = ctx.room_feats(
                obs.astype(np.float32)).astype(np.float64)
            Z = ctx.Z
            occ = float(obs[self.occ_idx]) if self.occ_idx >= 0 else 0.0
            now = float(obs[self.now_idx]) if self.now_idx >= 0 else 0.0
            soon = float(obs[self.soon_idx]) if self.soon_idx >= 0 else 0.0
            tw = self._water_kelvin(obs)
            oat = self._oat_kelvin(obs)
            t_now = np.array([
                obs[r["temp_obs"]] * ctx.z_std + ctx.z_mean
                for r in ctx.rooms])
            if self._prev_t is None:
                self._prev_t = t_now.copy()
                self._ema_t = t_now.copy()
                self._int_z = np.zeros(Z)
                self._heat_ema = np.zeros(ctx.A)
                self._cool_ema = np.zeros(ctx.A)
                self._int_w = 0.0
            center_err = (room[:, 0] - room[:, 1]) * 0.5
            zf = np.zeros((Z, self.FZ))
            zf[:, :8] = room
            zf[:, 8] = self._clip(occ / 50.0, -1.0, 3.0)
            zf[:, 9] = now
            zf[:, 10] = soon
            for k, r in enumerate(ctx.rooms):
                sat = self._sat_kelvin(obs, r["ahu"])
                zf[k, 11] = self._clip((sat - t_now[k]) / 10.0)
                run_i = ctx.ahu_cols[r["ahu"]]["supervisor_run_command"]
                zf[k, 12] = float(obs[run_i]) if run_i >= 0 else 0.0
                zf[k, 13] = self._clip((tw - t_now[k]) / 20.0)
                zf[k, 14] = (self._prev_t[k] - 294.0) / 6.0
                zf[k, 15] = (self._ema_t[k] - 294.0) / 6.0
            zf[:, 16] = self._clip(self._int_z / 20.0)
            zf[:, 17] = self._clip((oat - 280.0) / 20.0)
            self._prev_t = t_now.copy()
            self._ema_t = ((11.0 / 12.0) * self._ema_t
                           + (1.0 / 12.0) * t_now)
            self._int_z = (0.995 * self._int_z
                           + np.clip(center_err, -1.0, 1.0))
            A = ctx.A
            af = np.zeros((A, self.FA))
            for i in range(A):
                ks = [k for k, r in enumerate(ctx.rooms) if r["ahu"] == i]
                if ks:
                    rk = room[ks]
                    af[i, 0] = rk[:, 0].mean()
                    af[i, 1] = rk[:, 1].mean()
                    af[i, 2] = rk[:, 7].mean()
                    af[i, 3] = (-rk[:, 1]).max()
                    af[i, 4] = (-rk[:, 0]).max()
                    heat_need = np.clip(-rk[:, 1] * 4.0, 0.0, 1.0).mean()
                    cool_need = np.clip(-rk[:, 0] * 4.0, 0.0, 1.0).mean()
                else:
                    heat_need = cool_need = 0.0
                af[i, 12] = self._heat_ema[i]
                af[i, 13] = self._cool_ema[i]
                self._heat_ema[i] += (heat_need - self._heat_ema[i]) / 12.0
                self._cool_ema[i] += (cool_need - self._cool_ema[i]) / 12.0
                af[i, 5] = self._clip((oat - 280.0) / 20.0)
                sat = self._sat_kelvin(obs, i)
                af[i, 6] = (sat - 291.0) / 10.0
                cols = ctx.ahu_cols[i]
                pi = cols["supply_air_static_pressure_sensor"]
                af[i, 7] = float(obs[pi]) / 1000.0 if pi >= 0 else 0.2
                fi = cols["supply_air_flowrate_sensor"]
                af[i, 8] = float(obs[fi]) / 4.0 if fi >= 0 else 0.0
                run_i = cols["supervisor_run_command"]
                af[i, 9] = float(obs[run_i]) if run_i >= 0 else 0.0
                rc = cols["recirculation_percentage_command"]
                af[i, 10] = float(obs[rc]) if rc >= 0 else 0.0
                cr = cols["cooling_request_count"]
                af[i, 11] = float(obs[cr]) / 4.0 if cr >= 0 else 0.0
            gf = np.zeros((self.FG,))
            gf[0] = self._clip(occ / 50.0, -1.0, 3.0)
            gf[1] = now
            gf[2] = soon
            if Z:
                gf[3] = room[:, 0].mean()
                gf[4] = room[:, 1].mean()
                gf[5] = room[:, 7].mean()
            gf[6] = (tw - 330.0) / 20.0
            gf[7] = (float(obs[self.hws_press]) / 10.0
                     if self.hws_press >= 0 else 0.0)
            gf[8] = float(obs[self.hws_run]) if self.hws_run >= 0 else 0.0
            gf[9] = self._clip((oat - 280.0) / 20.0)
            shortfall = float(np.mean(np.clip(-room[:, 1], 0.0, None))
                              if Z else 0.0)
            gf[10] = self._clip(self._int_w / 50.0)
            self._int_w = 0.995 * self._int_w + shortfall
            return bank, slot, (np.nan_to_num(zf).astype(np.float32),
                                np.nan_to_num(af).astype(np.float32),
                                np.nan_to_num(gf).astype(np.float32))

    # -- policy ----------------------------------------------------------
    def __init__(self, building_meta_data, action_spec):
        import base64
        import io
        import zlib
        super().__init__(building_meta_data, action_spec)
        self._feat = self._SFeat(building_meta_data)
        w = np.load(io.BytesIO(zlib.decompress(
            base64.b64decode(RESID30_W_B64))))
        self.Wz = w["Wz"].astype(np.float32)
        self.bz = w["bz"].astype(np.float32)
        self.Wa = w["Wa"].astype(np.float32)
        self.ba = w["ba"].astype(np.float32)
        self.Wg = w["Wg"].astype(np.float32)
        self.bg = w["bg"].astype(np.float32)
        bw = np.asarray(self.BLEND, dtype=np.float64)
        self._blend = bw / bw.sum()
        self._half = len(self._blend) // 2

    def reset(self):
        super().reset()
        feat = getattr(self, "_feat", None)
        if feat is not None:
            feat.reset()

    def _blended(self, W, b, bank, slot):
        Wm = np.zeros_like(W[bank, slot], dtype=np.float64)
        bm = np.zeros_like(b[bank, slot], dtype=np.float64)
        for j, w in enumerate(self._blend):
            s = (slot + j - self._half) % self.N_SLOTS
            Wm += w * W[bank, s]
            bm += w * b[bank, s]
        return Wm, bm

    def _chain_action(self, obs):
        action = super()._chain_action(obs)
        bank, slot, (zf, af, gf) = self._feat.step(np.asarray(obs))
        Wz, bz = self._blended(self.Wz, self.bz, bank, slot)
        Wa, ba = self._blended(self.Wa, self.ba, bank, slot)
        Wg, bg = self._blended(self.Wg, self.bg, bank, slot)
        zone = zf.astype(np.float64) @ Wz + bz
        ahu = af.astype(np.float64) @ Wa + ba
        wat = gf.astype(np.float64) @ Wg + bg
        s = self.RESID_SCALE
        cont = action["continuous_action"]
        for k, r in enumerate(self._feat.ctx.rooms):
            cont[r["damp_act"]] = np.float32(np.clip(
                float(cont[r["damp_act"]]) + s * zone[k, 0], -1.0, 1.0))
            cont[r["reheat_act"]] = np.float32(np.clip(
                float(cont[r["reheat_act"]]) + s * zone[k, 1], -1.0, 1.0))
        for i, act in enumerate(self._feat.ctx.ahu_actions):
            cont[act["temp_idx"]] = np.float32(np.clip(
                float(cont[act["temp_idx"]]) + s * ahu[i, 0], -1.0, 1.0))
            if act["pressure_idx"] is not None:
                cont[act["pressure_idx"]] = np.float32(np.clip(
                    float(cont[act["pressure_idx"]]) + s * ahu[i, 1],
                    -1.0, 1.0))
            if act["recirc_idx"] is not None:
                cont[act["recirc_idx"]] = np.float32(np.clip(
                    float(cont[act["recirc_idx"]]) + s * ahu[i, 2],
                    -1.0, 1.0))
        w = self._feat.ctx.water
        if w["water_temp_idx"] is not None:
            cont[w["water_temp_idx"]] = np.float32(np.clip(
                float(cont[w["water_temp_idx"]]) + s * wat[0], -1.0, 1.0))
        if w["water_pressure_idx"] is not None:
            cont[w["water_pressure_idx"]] = np.float32(np.clip(
                float(cont[w["water_pressure_idx"]]) + s * wat[1],
                -1.0, 1.0))
        return action
